class TestAnalyzeResults:
    def test_analyze_numeric_results(self, client):
        results = {
            "columns": ["amount"],
            "rows": [[10], [20], [30]],
        }
        analysis = client.analyze_results(results)
        assert analysis["row_count"] == 3
        stats = analysis["numeric_stats"]["amount"]
        assert stats["min"] == 10
        assert stats["max"] == 30
        assert stats["sum"] == 60
        assert stats["avg"] == 20.0

    def test_analyze_empty_results(self, client):
        results = {"columns": [], "rows": []}
        analysis = client.analyze_results(results)
        assert analysis["row_count"] == 0

    def test_analyze_error_results(self, client):
        results = {"error": "Something went wrong"}
        analysis = client.analyze_results(results)
        assert "error" in analysis

